    if n == 0:
        return '0'
    result = ''
    while n != 0:
        remainder = n % 3
        n //= 3
        if remainder == 2:
            result = '-' + result
            n += 1
        elif remainder == 1:
            result = '+' + result
        else:
            result = '0' + result
    return result.lstrip('0')
