import re

def is_allowed_webhook(url: str) -> bool:
    # Check if the URL starts with 'https://'
    if not url.startswith('https://'):
        return False

    # Check if the URL contains any backslash, space, or control character
    if any(c in url for c in ['/', ' ', '\t', '\n', '\r', '\f', '\v']):
        return False

    # Check if the URL contains any non-ASCII character
    if any(not chr(c).isascii() for c in url):
        return False

    # Check if the host is a valid DNS name
    host = url.split('/')[2].split(':')[0]
    if not re.match(r'^(?:[a-zA-Z0-9]+\.)*[a-zA-Z0-9]+$', host):
        return False

    # Check if the port is 443
    port = url.split(':')[-1].split('/')[0]
    if port != '443':
        return False

    return True

