        return False

    # Check if URL contains any backslash, space, or control character
    if any(char in url for char in ['/', ' ', '\t', '\n', '\r', '\f', '\v']):
        return False

    # Check if URL contains any non-ASCII character
    if not all(ord(char) < 128 for char in url):
        return False

    # Check if host is a valid DNS name
    parsed_url = urlparse.urlparse(url)
    if not re.match(r'^(?:[a-zA-Z0-9]+\.)*[a-zA-Z0-9]+$', parsed_url.hostname):
        return False

    # Check if port is 443
    if parsed_url.port and parsed_url.port != 443:
        return False

    return True

