def is_perfect_square(n: int) -> bool:
    if n < 0:
        return False
    if n == 0 or n == 1:
        return True
    x = n // 2
    seen = set()
    while x * x != n:
        if x in seen:
            return False
        seen.add(x)
        x = (x + (n // x)) // 2
    return True

