            return eval(self.safe_expression(expression))
        except ZeroDivisionError:
            raise ZeroDivisionError("Cannot divide by zero.")
        except ValueError:
            raise ValueError("Invalid value in expression.")
        except SyntaxError:
            raise InvalidExpressionError("Invalid expression syntax.")

