                result = operators[token](operand1)
            elif token in ['AND', 'OR'] and len(stack) >= 2:
                operand2 = stack.pop()
                operand1 = stack.pop()
                result = operators[token](operand1, operand2)
            else:
                raise ValueError('Invalid expression')
            stack.append(result)
        else:
            if token in record:
                stack.append(record[token])
            else:
                raise KeyError('Variable not found in record')

    return stack[0]
